{
  "hypotheses": [
    {
      "text": "Multiple rows arise from amended filings (e.g., original 10‑K followed by 10‑K/A) where the same fiscal‑year revenue fact is re‑reported with a new accession number.",
      "how_to_test": "SELECT COUNT(*) AS total_rows, COUNT(DISTINCT accession_number) AS distinct_accessions, COUNT(DISTINCT form_type) AS distinct_forms FROM edgar.revenue_facts WHERE cik = 320193 AND fiscal_year = 2022 AND concept IN ('Revenues','RevenueFromContractWithCustomerExcludingAssessedTax');\n-- If total_rows > distinct_accessions, duplicates exist due to re‑filings."
    },
    {
      "text": "The count includes both the annual FY2022 figure and the four quarterly FY2022 figures (Q1‑Q4) because the query did not restrict fiscal_period to 'FY'.",
      "how_to_test": "SELECT fiscal_period, COUNT(*) AS rows FROM edgar.revenue_facts WHERE cik = 320193 AND fiscal_year = 2022 AND concept IN ('Revenues','RevenueFromContractWithCustomerExcludingAssessedTax') GROUP BY fiscal_period ORDER BY fiscal_period;\n-- Expect rows for 'FY' plus 'Q1'..'Q4' if this hypothesis holds."
    },
    {
      "text": "Two different XBRL concepts ('Revenues' and 'RevenueFromContractWithCustomerExcludingAssessedTax') are both stored, producing two rows per filing (one for each concept).",
      "how_to_test": "SELECT concept, COUNT(*) AS rows FROM edgar.revenue_facts WHERE cik = 320193 AND fiscal_year = 2022 GROUP BY concept;\n-- If each concept shows roughly half the total rows, this explains the multiplicity."
    },
    {
      "text": "Ingestion duplication: the same fact appears multiple times in the source data (e.g., loaded from both the daily and weekly snapshots) resulting in identical rows with different period_frame values or NULL period_frame.",
      "how_to_test": "SELECT accession_number, period_frame, COUNT(*) AS dup_count FROM edgar.revenue_facts WHERE cik = 320193 AND fiscal_year = 2022 AND concept IN ('Revenues','RevenueFromContractWithCustomerExcludingAssessedTax') GROUP BY accession_number, period_frame HAVING COUNT(*) > 1;\n-- Any groups with dup_count > 1 indicate duplicate rows."
    }
  ]
}
